#include "screen_builder.h"
#include "screen_model.h"
#include "event_tools.h"
#include "world_editor.h"
#include <QtWidgets>
namespace cf {
ScreenCanvas::ScreenCanvas(QWidget *p):QWidget(p){setFixedSize(480,432);setMouseTracking(true);}
void ScreenCanvas::paintEvent(QPaintEvent*){QPainter painter(this);painter.scale(zoom,zoom);if(scene<0||scene>=project.scenes.size())return;painter.drawImage(0,0,sceneImage(project,project.scenes[scene]));if(grid){painter.setPen(QPen(QColor(70,90,110,70),.2));for(int x=0;x<=20;++x)painter.drawLine(x*8,0,x*8,144);for(int y=0;y<=18;++y)painter.drawLine(0,y*8,160,y*8);}if(selected>=0&&selected<project.scenes[scene].elements.size()){auto r=project.scenes[scene].elements[selected].rect;painter.setPen(QPen(QColor("#f18b4b"),.7));painter.setBrush(Qt::NoBrush);painter.drawRect(r.x()*8,r.y()*8,r.width()*8,r.height()*8);painter.fillRect((r.right()+1)*8-3,(r.bottom()+1)*8-3,3,3,QColor("#f18b4b"));}}
void ScreenCanvas::mousePressEvent(QMouseEvent *e){if(scene<0||scene>=project.scenes.size())return;auto point=e->position().toPoint()/zoom;auto &v=project.scenes[scene].elements;int hit=-1;for(int i=v.size()-1;i>=0;--i)if(QRect(v[i].rect.topLeft()*8,v[i].rect.size()*8).contains(point)){hit=i;break;}selected=hit;if(onSelect)onSelect(hit);if(hit>=0){anchor=point/8;original=v[hit].rect;resizing=point.x()>(original.right()+1)*8-5&&point.y()>(original.bottom()+1)*8-5;dragging=true;}update();}
void ScreenCanvas::mouseMoveEvent(QMouseEvent *e){if(!dragging||selected<0)return;auto delta=e->position().toPoint()/(zoom*8)-anchor;auto r=original;if(resizing)r.setSize({qBound(1,original.width()+delta.x(),20-original.x()),qBound(1,original.height()+delta.y(),18-original.y())});else r.moveTo(qBound(0,original.x()+delta.x(),20-original.width()),qBound(0,original.y()+delta.y(),18-original.height()));project.scenes[scene].elements[selected].rect=r;update();}
void ScreenCanvas::mouseReleaseEvent(QMouseEvent*){if(dragging&&selected>=0&&onRect){auto r=project.scenes[scene].elements[selected].rect;dragging=false;if(r!=original)onRect(r);}dragging=false;}
void ScreenCanvas::wheelEvent(QWheelEvent *e){if(e->modifiers()&(Qt::ControlModifier|Qt::MetaModifier)){zoom=qBound(1,zoom+(e->angleDelta().y()>0?1:-1),8);setFixedSize(160*zoom,144*zoom);update();e->accept();}else QWidget::wheelEvent(e);}
ScreenBuilder::ScreenBuilder(QWidget *p):QWidget(p){auto *root=new QHBoxLayout(this);auto *left=new QVBoxLayout;left->addWidget(new QLabel("SCENES"));scenes=new QComboBox;left->addWidget(scenes);auto *sceneButtons=new QHBoxLayout;auto *create=new QPushButton("+ Scene"),*test=new QPushButton("Test Scene"),*preview=new QPushButton("Preview");sceneButtons->addWidget(create);sceneButtons->addWidget(test);sceneButtons->addWidget(preview);left->addLayout(sceneButtons);elements=new QListWidget;left->addWidget(elements,1);auto *addType=new QComboBox;addType->addItems({"Text","Button","Panel","Image"});left->addWidget(addType);auto *addButton=new QPushButton("+ Add element");left->addWidget(addButton);auto *order=new QHBoxLayout;auto *up=new QPushButton("Raise"),*down=new QPushButton("Lower"),*remove=new QPushButton("Remove");order->addWidget(up);order->addWidget(down);order->addWidget(remove);left->addLayout(order);root->addLayout(left,1);auto *middle=new QVBoxLayout;auto *tools=new QHBoxLayout;auto *zoom=new QSpinBox;zoom->setRange(1,8);zoom->setValue(3);zoom->setSuffix("×");tools->addWidget(new QLabel("Zoom"));tools->addWidget(zoom);auto *grid=new QCheckBox("Tile grid");grid->setChecked(true);tools->addWidget(grid);tools->addStretch();middle->addLayout(tools);canvas=new ScreenCanvas;auto *scroll=new QScrollArea;scroll->setWidget(canvas);scroll->setAlignment(Qt::AlignCenter);middle->addWidget(scroll,1);info=new QLabel("Select an element. Drag to move; drag its bottom-right handle to resize.\nButtons: Up/Down selects, A activates. B runs the scene's onBack event.");info->setWordWrap(true);middle->addWidget(info);root->addLayout(middle,3);auto *inspector=new QScrollArea;inspector->setWidgetResizable(true);inspector->setMinimumWidth(330);auto *fields=new QWidget;form=new QFormLayout(fields);form->setFieldGrowthPolicy(QFormLayout::AllNonFixedFieldsGrow);inspector->setWidget(fields);root->addWidget(inspector,2);connect(scenes,&QComboBox::currentIndexChanged,this,[this](int i){if(filling)return;active=i;selected=-1;list();inspect();});connect(elements,&QListWidget::currentRowChanged,this,[this](int i){if(filling)return;selected=i;canvas->selected=i;canvas->update();inspect();});connect(create,&QPushButton::clicked,this,[this]{if(project.scenes.size()>=32)return;edit([&](Project&p){p.scenes<<Scene{"scene_"+QUuid::createUuid().toString(QUuid::Id128).left(16),"New scene"};active=p.scenes.size()-1;selected=-1;},true);});connect(preview,&QPushButton::clicked,this,[this]{if(active<0||active>=project.scenes.size())return;auto errors=project.validate();if(!errors.isEmpty()){QMessageBox::warning(this,"Cannot preview yet",errors.join('\n'));return;}QDialog dialog(this);dialog.setWindowTitle("Scene preview — "+project.scenes[active].name);auto *layout=new QVBoxLayout(&dialog);auto *play=new WorldPlay;play->setProject(project);play->startScene(project.scenes[active].id);layout->addWidget(play);auto *hint=new QLabel("Click to play · Arrows: move/select · Z: A · X: B · Backspace: inventory");layout->addWidget(hint);auto *close=new QDialogButtonBox(QDialogButtonBox::Close);layout->addWidget(close);connect(close,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.exec();});connect(test,&QPushButton::clicked,this,[this]{if(active<0||active>=project.scenes.size())return;auto p=project;p.defaultScene=p.scenes[active].id;if(onTest)onTest(p);});connect(addButton,&QPushButton::clicked,this,[this,addType]{add(addType->currentText().toLower());});connect(remove,&QPushButton::clicked,this,[this]{if(selected<0)return;edit([&](Project&p){p.scenes[active].elements.removeAt(selected);selected=-1;},true);});auto reorder=[this](int direction){if(selected<0)return;int next=qBound(0,selected+direction,int(project.scenes[active].elements.size())-1);edit([&](Project&p){p.scenes[active].elements.swapItemsAt(selected,next);selected=next;},true);};connect(up,&QPushButton::clicked,this,[reorder]{reorder(1);});connect(down,&QPushButton::clicked,this,[reorder]{reorder(-1);});connect(zoom,&QSpinBox::valueChanged,this,[this](int v){canvas->zoom=v;canvas->setFixedSize(v*160,v*144);canvas->update();});connect(grid,&QCheckBox::toggled,this,[this](bool v){canvas->grid=v;canvas->update();});canvas->onSelect=[this](int i){selected=i;filling=true;elements->setCurrentRow(i);filling=false;inspect();};canvas->onRect=[this](QRect r){if(selected>=0)edit([&](Project&p){p.scenes[active].elements[selected].rect=r;},true);};}
void ScreenBuilder::setProject(const Project&p){project=p;if(editing){canvas->project=p;canvas->update();return;}active=qBound(0,active,qMax(0,int(p.scenes.size())-1));filling=true;scenes->clear();for(auto&s:p.scenes)scenes->addItem((s.id==p.defaultScene?"▶ ":"")+s.name+" ["+s.kind+"]");scenes->setCurrentIndex(active);filling=false;list();inspect();}
void ScreenBuilder::selectScene(int i){scenes->setCurrentIndex(i);}
void ScreenBuilder::list(){filling=true;elements->clear();if(active>=0&&active<project.scenes.size())for(auto&e:project.scenes[active].elements)elements->addItem(e.name+" ["+e.type+"]");selected=qBound(-1,selected,int(elements->count())-1);elements->setCurrentRow(selected);filling=false;auto errors=project.validate();info->setText(errors.isEmpty()?"Select an element. Drag to move; drag its bottom-right handle to resize.\nButtons: Up/Down selects, A activates. B runs onBack.":"Build needs attention: "+errors.mid(0,2).join(" · "));canvas->project=project;canvas->scene=active;canvas->selected=selected;canvas->update();}
void ScreenBuilder::edit(const std::function<void(Project&)>&fn,bool refill){fn(project);auto errors=project.validate();info->setText(errors.isEmpty()?"Select an element. Drag to move; drag its bottom-right handle to resize.\nButtons: Up/Down selects, A activates. B runs onBack.":"Build needs attention: "+errors.mid(0,2).join(" · "));editing=true;if(onEdit)onEdit(project);editing=false;if(refill)setProject(project);else{canvas->project=project;canvas->update();}}
void ScreenBuilder::add(QString type){if(active<0||active>=project.scenes.size()||project.scenes[active].elements.size()>=16)return;ScreenElement e;e.type=type;e.id="element_"+QUuid::createUuid().toString(QUuid::Id128);e.name=type;e.text=type=="button"?"Start":type=="text"?"New text":"";e.rect=type=="panel"?QRect(1,1,18,16):QRect(2,6,16,2);edit([&](Project&p){p.scenes[active].elements<<e;selected=p.scenes[active].elements.size()-1;},true);}
void ScreenBuilder::inspect(){while(form->rowCount())form->removeRow(0);if(active<0||active>=project.scenes.size())return;auto scene=project.scenes[active];auto text=[&](QString label,QString value,auto fn){auto *w=new QLineEdit(value);form->addRow(label,w);connect(w,&QLineEdit::textEdited,this,[this,fn](QString s){edit([&](Project&p){fn(p,s);});});};if(selected<0){form->addRow("Scene ID",new QLabel(scene.id));text("Scene name",scene.name,[this](Project&p,QString s){p.scenes[active].name=s;});auto *kind=new QComboBox;kind->addItem("Screen (menus, title, HUD)","screen");kind->addItem("World (maps & navigation)","world");kind->setCurrentIndex(kind->findData(scene.kind));form->addRow("Scene type",kind);connect(kind,&QComboBox::activated,this,[this,kind]{edit([&](Project&p){auto&s=p.scenes[active];s.kind=kind->currentData().toString();if(s.kind=="world"&&s.startArea.isEmpty())for(auto &a:p.allAreas())if(p.areaScene(a.id)==s.id){s.startArea=a.id;break;}},true);});if(scene.kind=="world"){auto *areas=new QComboBox;areas->addItem("Choose an area",QString());for(auto&a:project.allAreas())if(project.areaScene(a.id)==scene.id)areas->addItem(a.name,a.id);areas->setCurrentIndex(qMax(0,areas->findData(scene.startArea)));form->addRow("Initial area",areas);connect(areas,&QComboBox::activated,this,[this,areas]{edit([&](Project&p){p.scenes[active].startArea=areas->currentData().toString();});});}auto *color=new QPushButton("Background colour…");form->addRow(color);connect(color,&QPushButton::clicked,this,[this]{auto c=QColorDialog::getColor(rgb555(project.scenes[active].background),this);if(c.isValid())edit([&](Project&p){p.scenes[active].background=toRgb555(c);});});for(int ev=0;ev<2;++ev){auto *source=new QPlainTextEdit(ev?scene.onBack:scene.onSceneEnter);source->setMinimumHeight(120);form->addRow(ev?"onBack":"onSceneEnter",eventTools(source,[this]{return project;}));connect(source,&QPlainTextEdit::textChanged,this,[this,source,ev]{edit([&](Project&p){if(ev)p.scenes[active].onBack=source->toPlainText();else p.scenes[active].onSceneEnter=source->toPlainText();});});}form->addRow(new QLabel("Startup: splash → File / Project Settings / Default Scene → onSceneEnter.\nFor world scenes, onAreaEnter runs before onSceneEnter."));return;}
auto e=scene.elements[selected];form->addRow("Element ID",new QLabel(e.id));text("Name",e.name,[this](Project&p,QString s){p.scenes[active].elements[selected].name=s;});for(int d=0;d<4;++d){auto *spin=new QSpinBox;spin->setRange(d<2?0:1,d%2?18:20);spin->setValue(d==0?e.rect.x():d==1?e.rect.y():d==2?e.rect.width():e.rect.height());form->addRow(QStringList{"X (tiles)","Y (tiles)","Width (tiles)","Height (tiles)"}[d],spin);connect(spin,&QSpinBox::valueChanged,this,[this,d](int v){edit([&](Project&p){auto&r=p.scenes[active].elements[selected].rect;if(d==0)r.moveLeft(qMin(v,20-r.width()));if(d==1)r.moveTop(qMin(v,18-r.height()));if(d==2)r.setWidth(qMin(v,20-r.x()));if(d==3)r.setHeight(qMin(v,18-r.y()));});});}if(e.type=="text"||e.type=="button"){auto *body=new QPlainTextEdit(e.text);form->addRow("Text ({variable} supported)",body);connect(body,&QPlainTextEdit::textChanged,this,[this,body]{edit([&](Project&p){p.scenes[active].elements[selected].text=body->toPlainText();});});auto *align=new QComboBox;align->addItems({"Left","Centre","Right"});align->setCurrentIndex(e.align);form->addRow("Alignment",align);connect(align,&QComboBox::activated,this,[this](int v){edit([&](Project&p){p.scenes[active].elements[selected].align=v;});});}if(e.type=="image"){auto *assets=new QComboBox;assets->addItem("Choose an image",QString());for(auto&a:project.assets)assets->addItem(a.name,a.id);assets->setCurrentIndex(qMax(0,assets->findData(e.image)));form->addRow("Asset (scaled to rectangle)",assets);connect(assets,&QComboBox::activated,this,[this,assets]{edit([&](Project&p){p.scenes[active].elements[selected].image=assets->currentData().toString();});});auto *import=new QPushButton("Import screen image…");form->addRow(import);connect(import,&QPushButton::clicked,this,[this]{auto path=QFileDialog::getOpenFileName(this,"Import screen image",{},"Images (*.png *.jpg *.bmp *.gif)");if(path.isEmpty())return;QImage image(path);if(image.isNull()){QMessageBox::warning(this,"Cannot import","The image could not be decoded.");return;}ImportOptions opts;opts.screen=true;opts.width=160;opts.height=144;auto a=convertImage(image,opts);a.id="screen_"+QUuid::createUuid().toString(QUuid::Id128);a.name=QFileInfo(path).completeBaseName();edit([&](Project&p){p.assets<<a;p.scenes[active].elements[selected].image=a.id;p.scenes[active].elements[selected].rect={0,0,20,18};},true);});}if(e.type=="button"){auto *condition=new QLineEdit(e.condition);form->addRow("Enabled when",conditionTools(condition,[this]{return project;}));connect(condition,&QLineEdit::textChanged,this,[this,condition]{edit([&](Project&p){p.scenes[active].elements[selected].condition=condition->text();});});auto *source=new QPlainTextEdit(e.actions);source->setMinimumHeight(140);form->addRow("On activate",eventTools(source,[this]{return project;}));connect(source,&QPlainTextEdit::textChanged,this,[this,source]{edit([&](Project&p){p.scenes[active].elements[selected].actions=source->toPlainText();});});}}
}
